<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Falling Sand Sandbox</title>
<style>
  :root { --bg-color: #1a1a1a; --text-color: #dcdcdc; }
  body { 
    margin: 0; padding: 20px; background: var(--bg-color); color: var(--text-color); 
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; 
    display: flex; flex-direction: column; align-items: center; min-height: 100vh; box-sizing: border-box;
  }

  h1 { margin: 0 0 15px 0; font-weight: 400; letter-spacing: 1px; }

  #controls { 
    width: 400px; display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin-bottom: 15px;
  }

  button { 
    background: #333; color: var(--text-color); border: 1px solid #444; padding: 6px 2px; 
    cursor: pointer; font-size: 0.85em; border-radius: 4px; transition: all 0.1s; outline: none;
  }
  button:hover { background: #3e3e3e; }

  /* Active Selection Styles */
  .active { box-shadow: inset 0 0 0 2px var(--highlight); border-color: var(--highlight); color: white; font-weight: bold; }

  :root {
    --c-empty: transparent; --c-wall: #7a7a7a; --c-sand: #dcb35c; 
    --c-water: #4facfe; --c-acid: #ff4d4d; --highlight: rgba(255, 255, 255, 0.5);
  }

  .btn-empty.active { background: #111; border-color: #444; color: #888; box-shadow: none; }
  .btn-wall.active { background: var(--c-wall); color: white; }
  .btn-sand.active { background: var(--c-sand); color: black; }
  .btn-water.active { background: var(--c-water); color: white; }
  .btn-acid.active { background: var(--c-acid); color: white; border-color: #ff0000; }

  canvas { 
    width: 400px; height: 400px; /* CSS pixels */ 
    image-rendering: pixelated; cursor: crosshair;
    background: transparent; 
    border-radius: 6px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    touch-action: none; /* Prevent scrolling while painting */
  }

  .instructions { font-size: 0.8em; opacity: 0.7; margin-top: 10px; text-align: center; }
</style>
</head>
<body>

<h1>Falling Sand Sandbox</h1>

<div id="controls">
 <button id="mat-empty" class="active">Eraser</button>
 <button id="mat-wall">Wall</button>
 <button id="mat-sand">Sand</button>
 <button id="mat-water">Water</button>
 <button id="mat-acid">Acid</button>
 <div style="grid-column: span 2;"></div> <!-- Spacer -->
 <button id="clear" class="btn-eraser">Clear All</button>
</div>

<canvas id="sand"></canvas>

<div class="instructions">
 Left click / drag to paint selected material.<br>
 Material sinks into liquid (Swap logic). Acid erodes walls and sand.
</div>

<script>
/**
 * Falling Sand Simulation Implementation
 * Grid: 80x80 cells
 * Materials: 'empty', 'wall', 'sand', 'water', 'acid'
 */

// --- Constants & Config ---
const W = 80; // Grid Width
const H = 80; // Grid Height
const SCALE_X = 5; // Visual Scale
const SCALE_Y = 5; // Visual Scale

// Internal Grid State
// We use strings directly in the grid for clarity and API compatibility
let grid = new Array(H).fill(null).map(() => new Array(W).fill('empty'));

// Color Map for Rendering
const COLORS = {
  'empty': null, 
  'wall': '#7a7a7a',
  'sand': '#dcb35c',
  'water': '#4facfe',
  'acid': '#ff4d4d'
};

// --- Simulation API (Window Global) ---
window.sim = {
  w: W,
  h: H,

  // Synchronous update of grid state
  tick: function(n) {
    for (let i = 0; i < n; i++) {
      processGrid();
    }
  },

  get: function(x, y) {
    if (x < 0 || x >= W || y < 0 || y >= H) return null;
    return grid[y][x];
  },

  set: function(x, y, material) {
    // Validate and clamp inputs
    if (material === 'empty') material = 'empty';
    else if (typeof material === 'string') material = material.toLowerCase();

    const safeX = Math.min(W - 1, Math.max(0, x));
    const safeY = Math.min(H - 1, Math.max(0, y));

    grid[safeY][safeX] = material;
  },

  clear: function() {
    // Reset logic state and trigger visual update via loop if running
    for(let y=0; y<H; y++) {
      for(let x=0; x<W; x++) {
        grid[y][x] = 'empty';
      }
    }
    draw(); // Immediate redraw to clear canvas (matches behavior of clicking Eraser)
  }
};

// --- Core Logic ---

function processGrid() {
  // Iterate bottom-up to ensure particles fall only one cell per tick step vertically
  // We skip the last row (bottom boundary) as it can't fall further down.
  for (let y = H - 2; y >= 0; y--) {
    for (let x = 0; x < W; x++) {
      const p = grid[y][x]; // Current particle

      if (p === 'empty' || p === 'wall') continue;

      if (p === 'sand') {
        moveSand(x, y);
      } else if (p === 'water' || p === 'acid') {
        moveLiquid(x, y);
      }
    }
  }
}

function moveSand(x, y) {
  const below = grid[y + 1][x];

  // Check vertical movement first: Sink/swap with liquid or fall into empty
  if (below === 'empty' || below === 'water' || below === 'acid') {
    grid[y + 1][x] = 'sand';   // Particle moves down
    grid[y][x] = below;        // Swap contents (Liquid/Empty comes up)
    return true;               // Moved
  }

  // Blocked vertically, try diagonal slide
  const directions = [
    {dx: -1, dy: 1}, // Down-Left
    {dx: 1, dy: 1}   // Down-Right
  ];

  // Randomize order to prevent bias
  if (Math.random() < 0.5) directions.reverse();

  for (let d of directions) {
    const nx = x + d.dx;
    const ny = y + d.dy;

    if (nx >= 0 && nx < W && ny < H) {
      const neighbor = grid[ny][nx];
      // Can enter empty or liquid (sand sinks)
      if (neighbor === 'empty' || neighbor === 'water' || neighbor === 'acid') {
        grid[ny][nx] = 'sand';
        grid[y][x] = neighbor;
        return true;
      }
    }
  }
}

function moveLiquid(x, y) {
  const p = grid[y][x]; // 'water' or 'acid'

  // Acid handles extra dissolution logic here. 
  // We check neighbors for potential erosion before moving out.
  if (p === 'acid') {
    dissolveNeighbors(x, y);
  }

  // Check Vertical Move (Falling / Swapping)
  const below = grid[y + 1][x];
  if (below === 'empty' || below === 'water' || below === 'acid') {
    grid[y + 1][x] = p;     // Liquid moves down
    grid[y][x] = below;     // Swap back original content
    return true;            // Moved vertically
  }

  // Check Horizontal Spread (if falling is blocked or bottom reached)
  const spreadResult = trySpread(x, y);
  if (spreadResult !== null) {
    return true;
  }
}

function trySpread(x, y) {
  // Liquid spreads sideways into empty, water, or acid (mixing)
  const dirs = [[1, 0], [-1, 0]];
  if (Math.random() < 0.5) dirs.reverse();

  for (let d of dirs) {
    const nx = x + d[0];
    if (nx >= 0 && nx < W) {
      const neighbor = grid[y][nx];
      if (neighbor === 'empty' || neighbor === 'water' || neighbor === 'acid') {
        grid[y][nx] = (grid[y][x]); // Place current liquid into empty slot
        grid[y][x] = neighbor;      // Push original content from nx to x
        return true;
      }
    }
  }
  return null;
}

function dissolveNeighbors(x, y) {
  const acidAt = (grid[y][x] === 'acid');
  if (!acidAt) return;

  // Touches below or beside
  const targets = [
    {x: x, y: y + 1},    // Below
    {x: x - 1, y: y},    // Left
    {x: x + 1, y: y}     // Right
  ];

  for (let t of targets) {
    if (t.x >= 0 && t.x < W && t.y < H) {
      const targetVal = grid[t.y][t.x];
      // Acid dissolves sand and walls (and acid itself)
      if (targetVal === 'sand' || targetVal === 'wall' || targetVal === 'acid') {
        grid[t.y][t.x] = 'empty'; 
        // Optional: consume acid particle instantly? Usually erosion is gradual.
        // If we want it to eat walls fast, maybe remove acid too. 
        // But standard sand behavior: particles exist while eating.
      }
    }
  }
}

function draw() {
  const cvs = document.getElementById('sand');
  const ctx = cvs.getContext('2d', { alpha: false });

  // Clear with background color to handle transparency
  ctx.fillStyle = '#1a1a1a'; 
  ctx.fillRect(0, 0, cvs.width, cvs.height);

  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const mat = grid[y][x];
      if (mat !== 'empty') {
        ctx.fillStyle = COLORS[mat];
        ctx.fillRect(x * SCALE_X, y * SCALE_Y, SCALE_X, SCALE_Y);
      }
    }
  }
}

// --- Initialization & Interaction ---

const canvas = document.getElementById('sand');
canvas.width = W * SCALE_X;
canvas.height = H * SCALE_Y;

let currentMaterial = 'sand';

function initUI() {
  // Bind buttons to selection
  const ids = ['mat-empty', 'mat-wall', 'mat-sand', 'mat-water', 'mat-acid'];

  ids.forEach(id => {
    const btn = document.getElementById(id);
    if (btn) {
      btn.addEventListener('click', () => {
        // Highlight active button
        document.querySelectorAll('#controls > button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        // Update internal cursor/material state
        const parts = id.replace('mat-', '').split('-')[0];
        currentMaterial = parts;
      });
    }
  });

  // Clear Button Logic
  const clearBtn = document.getElementById('clear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      window.sim.clear();
      document.querySelectorAll('#controls > button').forEach(b => b.classList.remove('active'));
      // Re-activate sand or empty? Prompt implies "Clear" empties grid, selection persists.
      const emptyBtn = document.getElementById('mat-empty');
      if(emptyBtn) emptyBtn.classList.add('active');
      currentMaterial = 'empty';
    });
  }

  // Mouse Painting Logic
  let isDrawing = false;

  canvas.addEventListener('mousedown', (e) => {
    isDrawing = true;
    paint(e);
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDrawing) return;
    paint(e);
  });

  window.addEventListener('mouseup', () => {
    isDrawing = false;
  });

  function paint(e) {
    const rect = canvas.getBoundingClientRect();
    // Calculate mouse position relative to canvas, scaling by CSS size
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const mx = Math.floor((e.clientX - rect.left) * scaleX);
    const my = Math.floor((e.clientY - rect.top) * scaleY);

    // Map to grid coordinates
    const gx = Math.floor(mx / SCALE_X);
    const gy = Math.floor(my / SCALE_Y);

    // Clamp
    sim.set(gx, gy, currentMaterial);
  }
}

// Animation Loop
function loop() {
  // Run simulation every frame (or small interval).
  // This keeps it "satisfying" and smooth.
  window.sim.tick(1); 
  draw();
  requestAnimationFrame(loop);
}

initUI();
draw(); // Initial static render
requestAnimationFrame(loop); // Start loop immediately
</script>
</body>
</html>
